<style>.wall-shell{max-width:1040px!important}.wall-hero{background:linear-gradient(135deg,#162d46,#2185d0);color:#fff;border-radius:18px;padding:24px;display:flex;justify-content:space-between;align-items:center}.composer-card,.social-post,.inbox-card{background:#fff;border:1px solid #e4ebf1;border-radius:16px;padding:18px;margin-top:16px;box-shadow:0 8px 28px rgba(22,45,70,.07)}.composer-trigger{display:flex;align-items:center;gap:12px;cursor:pointer}.social-avatar,.mini-avatar{display:grid;place-items:center;border-radius:50%;background:linear-gradient(135deg,#2185d0,#00b5ad);color:#fff;font-weight:700}.social-avatar{width:44px;height:44px}.mini-avatar{width:30px;height:30px;flex:none}.social-post header{display:flex;gap:11px;align-items:center}.social-post header small{display:block;color:#718096;margin-top:3px}.post-actions{margin-left:auto}.post-copy{font-size:1.08rem;line-height:1.65;margin:16px 0}.post-media img,.post-media video{width:100%;max-height:520px;object-fit:contain;border-radius:12px;background:#0e1720}.post-meta{border-top:1px solid #edf1f5;border-bottom:1px solid #edf1f5;padding:9px 0;color:#68778a}.social-comment{display:flex;gap:9px;margin:12px 0}.social-comment>div:last-child{background:#f3f6f9;border-radius:14px;padding:8px 12px}.social-comment p{margin:3px 0}.theme-ocean{border-top:5px solid #2185d0}.theme-sunset{border-top:5px solid #f2711c}.theme-forest{border-top:5px solid #21ba45}.theme-midnight{border-top:5px solid #6435c9}.private-message-card{padding:12px!important;border-radius:12px!important}@media(max-width:700px){.wall-hero{display:block}.wall-hero button{margin-top:12px}}</style>
