</div><section class="inbox-card" id="inboxView" style="display:none"><div class="ui clearing segment"><button class="ui left floated basic button" id="btnBackToWall"><i class="arrow left icon"></i>Kembali ke Wall</button><button class="ui right floated primary button" id="btnComposePrivate"><i class="edit icon"></i>Tulis Pesan</button></div><h3 class="ui dividing header"><i class="shield alternate icon"></i>Pesan Pribadi Terenkripsi</h3><div class="ui relaxed divided list"><?php foreach(($messages??[]) as $message):?><div class="item private-message-card" data-message-id="<?= (int)$message['id'] ?>"><i class="large envelope outline middle aligned icon"></i><div class="content"><div class="header"><?= htmlspecialchars($message['pengirim']) ?> → <?= htmlspecialchars($message['penerima']) ?> <?php if(!empty($message['is_ephemeral'])):?><span class="ui mini orange label">sementara</span><?php endif;?></div><div class="description"><?= nl2br(htmlspecialchars($message['content'])) ?></div><?php if(!empty($message['attachment_path'])):?><a class="ui mini basic button" href="<?= app_url('/wallchat/private/file?id='.(int)$message['id']) ?>"><i class="paperclip icon"></i><?= htmlspecialchars($message['attachment_name']) ?></a><?php endif;?><button class="ui mini basic green button btnReadPrivate" data-id="<?= (int)$message['id'] ?>">Sudah dibaca</button><button class="ui mini basic red button btnDeletePrivate" data-id="<?= (int)$message['id'] ?>">Hapus</button></div></div><?php endforeach;?><?php if(empty($messages)):?><div class="ui message">Belum ada pesan pribadi.</div><?php endif;?></div></section></div>
